import * as fs from 'fs';

const logPath = '<tmp>';
const content = fs.readFileSync(logPath, 'utf-8');
const lines = content.split(/\r?\n/).filter(line => line.trim() !== '');

const levelCounts: Record<string, number> = {};
const componentErrors: Record<string, number> = {};
const errorMessages: Set<string> = new Set();
const hourCounts: Record<string, number> = {};

const lineRegex = /^\[(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\] (\S+) \(([^)]+)\) - (.+)$/;

for (const line of lines) {
    const match = line.match(lineRegex);
    if (!match) continue;

    const [, timestamp, level, component, message] = match;

    levelCounts[level] = (levelCounts[level] || 0) + 1;

    if (level === 'ERROR') {
        componentErrors[component] = (componentErrors[component] || 0) + 1;
        errorMessages.add(message);
    }

    const hour = timestamp.split(' ')[1].substring(0, 2);
    hourCounts[hour] = (hourCounts[hour] || 0) + 1;
}

let out = '';
out += '=== Log Analysis ===\n';
out += '\n';
out += 'Entries by Level:\n';
const sortedLevels = Object.keys(levelCounts).sort();
for (const level of sortedLevels) {
    out += `  ${level}: ${levelCounts[level]}\n`;
}
out += '\n';

let maxErrComponent = '';
let maxErrCount = 0;
for (const [comp, count] of Object.entries(componentErrors)) {
    if (count > maxErrCount || (count === maxErrCount && comp < maxErrComponent)) {
        maxErrCount = count;
        maxErrComponent = comp;
    }
}
out += `Component with Most Errors: ${maxErrComponent} (${maxErrCount} errors)\n`;
out += '\n';

out += 'Unique Error Messages:\n';
const sortedMessages = Array.from(errorMessages).sort();
for (const msg of sortedMessages) {
    out += `  - ${msg}\n`;
}
out += '\n';

let maxHour = '';
let maxHourCount = 0;
for (const [hour, count] of Object.entries(hourCounts)) {
    if (count > maxHourCount || (count === maxHourCount && hour < maxHour)) {
        maxHourCount = count;
        maxHour = hour;
    }
}
out += `Busiest Hour: ${maxHour}:00 (${maxHourCount} entries)\n`;

process.stdout.write(out);

