use std::fs;
use std::collections::BTreeMap;

fn format_commas_int(n: i64) -> String {
    let s = n.to_string();
    let negative = s.starts_with('-');
    let digits: String = if negative { s[1..].to_string() } else { s };
    let bytes = digits.as_bytes();
    let len = bytes.len();
    let mut result = String::new();
    if negative {
        result.push('-');
    }
    for (i, b) in bytes.iter().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(*b as char);
    }
    result
}

fn format_commas_float(n: f64) -> String {
    let negative = n < 0.0;
    let abs = if negative { -n } else { n };
    let int_part = abs as i64;
    let frac_part = ((abs - abs as i64 as f64) * 100.0).round() as u32;
    let int_str = format_commas_int(int_part);
    if negative {
        format!("-{}.{:02}", int_str, frac_part)
    } else {
        format!("{}.{:02}", int_str, frac_part)
    }
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read file");

    let mut lines = content.lines();
    let _header = lines.next();

    let mut dept_salaries: BTreeMap<String, (f64, u32)> = BTreeMap::new();
    let mut highest_paid_name = String::new();
    let mut highest_paid_salary: i64 = 0;
    let mut total_budget: i64 = 0;

    for line in lines {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let fields: Vec<&str> = line.split(',').map(|s| s.trim()).collect();
        if fields.len() < 6 {
            continue;
        }
        let name = fields[1].to_string();
        let department = fields[2].to_string();
        let salary: i64 = fields[3].parse().expect("Failed to parse salary");

        let entry = dept_salaries.entry(department.clone()).or_insert((0.0, 0));
        entry.0 += salary as f64;
        entry.1 += 1;

        if salary > highest_paid_salary {
            highest_paid_salary = salary;
            highest_paid_name = name;
        }

        total_budget += salary;
    }

    println!("=== Salary Report ===");
    println!();
    println!("Average Salary by Department:");
    for (dept, (sum, count)) in &dept_salaries {
        let avg = sum / *count as f64;
        println!("  {}: ${}", dept, format_commas_float(avg));
    }
    println!();
    println!("Highest Paid: {} (${})", highest_paid_name, format_commas_int(highest_paid_salary));
    println!();
    println!("Departments with >2 employees:");
    for (dept, (_, count)) in &dept_salaries {
        if *count > 2 {
            println!("  {} ({} employees)", dept, count);
        }
    }
    println!();
    println!("Total Budget: ${}", format_commas_int(total_budget));
}

