import heapq

def main():
    with open("<tmp>", "r") as f:
        data = json.load(f)

    nodes = data["nodes"]
    edges = data["edges"]

    adj = {node: [] for node in nodes}
    for edge in edges:
        u = edge["from"]
        v = edge["to"]
        w = edge["weight"]
        adj[u].append((v, w))
        adj[v].append((u, w))

    dist = {node: float('inf') for node in nodes}
    dist["A"] = 0

    visited = set()
    heap = [(0, "A")]

    while heap:
        d, u = heapq.heappop(heap)
        if u in visited:
            continue
        visited.add(u)
        for v, w in adj[u]:
            if v not in visited:
                nd = d + w
                if nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(heap, (nd, v))

    print("=== Shortest Paths from A ===")
    print()
    for node in sorted(nodes):
        d = dist[node]
        if d == float('inf'):
            print(f"A -> {node}: unreachable")
        elif d == int(d):
            print(f"A -> {node}: {int(d)}")
        else:
            print(f"A -> {node}: {d}")

main()

