import java.io.*;
import java.net.*;
import java.util.*;
import java.util.stream.*;

public class Main {

    static class JsonParser {
        private final String s;
        private int i;

        JsonParser(String s) {
            this.s = s;
            this.i = 0;
        }

        Object parse() {
            skipWs();
            if (i >= s.length()) return null;
            char c = s.charAt(i);
            if (c == '[') return parseArray();
            if (c == '{') return parseObject();
            if (c == '"') return parseString();
            if (c == 't' || c == 'f') return parseBool();
            if (c == 'n') { i += 4; return null; }
            return parseNumber();
        }

        private void skipWs() {
            while (i < s.length() && Character.isWhitespace(s.charAt(i))) i++;
        }

        private List<Object> parseArray() {
            List<Object> list = new ArrayList<>();
            i++; // skip [
            skipWs();
            if (i < s.length() && s.charAt(i) == ']') { i++; return list; }
            while (true) {
                skipWs();
                list.add(parse());
                skipWs();
                if (i < s.length() && s.charAt(i) == ',') { i++; }
                else { i++; break; } // skip ]
            }
            return list;
        }

        private Map<String, Object> parseObject() {
            Map<String, Object> map = new LinkedHashMap<>();
            i++; // skip {
            skipWs();
            if (i < s.length() && s.charAt(i) == '}') { i++; return map; }
            while (true) {
                skipWs();
                String key = parseString();
                skipWs();
                i++; // skip :
                Object val = parse();
                map.put(key, val);
                skipWs();
                if (i < s.length() && s.charAt(i) == ',') { i++; }
                else { i++; break; } // skip }
            }
            return map;
        }

        private String parseString() {
            i++; // skip opening "
            StringBuilder sb = new StringBuilder();
            while (i < s.length()) {
                char c = s.charAt(i);
                if (c == '\\') {
                    i++;
                    char esc = s.charAt(i);
                    switch (esc) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'n': sb.append('\n'); break;
                        case 't': sb.append('\t'); break;
                        case 'r': sb.append('\r'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'u':
                            String hex = s.substring(i + 1, i + 5);
                            sb.append((char) Integer.parseInt(hex, 16));
                            i += 4;
                            break;
                    }
                } else if (c == '"') {
                    i++;
                    return sb.toString();
                } else {
                    sb.append(c);
                }
                i++;
            }
            return sb.toString();
        }

        private Object parseBool() {
            if (s.charAt(i) == 't') { i += 4; return Boolean.TRUE; }
            else { i += 5; return Boolean.FALSE; }
        }

        private Object parseNumber() {
            int start = i;
            while (i < s.length() && (Character.isDigit(s.charAt(i)) || s.charAt(i) == '-'
                    || s.charAt(i) == '+' || s.charAt(i) == '.' || s.charAt(i) == 'e' || s.charAt(i) == 'E')) {
                i++;
            }
            String numStr = s.substring(start, i);
            if (numStr.contains(".") || numStr.contains("e") || numStr.contains("E")) {
                return Double.parseDouble(numStr);
            }
            return Long.parseLong(numStr);
        }
    }

    public static void main(String[] args) throws Exception {
        URL url = new URL("http://127.0.0.1:18923/api/products");
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("GET");
        conn.setConnectTimeout(10000);
        conn.setReadTimeout(10000);

        int status = conn.getResponseCode();
        InputStream is = (status >= 200 && status < 300) ? conn.getInputStream() : conn.getErrorStream();

        StringBuilder sb = new StringBuilder();
        try (BufferedReader br = new BufferedReader(new InputStreamReader(is, "UTF-8"))) {
            String line;
            while ((line = br.readLine()) != null) {
                sb.append(line);
            }
        }
        conn.disconnect();

        String json = sb.toString();
        JsonParser parser = new JsonParser(json);
        Object root = parser.parse();

        @SuppressWarnings("unchecked")
        List<Object> products = (List<Object>) root;

        List<Map<String, Object>> filtered = new ArrayList<>();
        for (Object obj : products) {
            @SuppressWarnings("unchecked")
            Map<String, Object> p = (Map<String, Object>) obj;
            double price = ((Number) p.get("price")).doubleValue();
            if (price > 50.00) {
                filtered.add(p);
            }
        }

        filtered.sort((a, b) -> {
            String nameA = (String) a.get("name");
            String nameB = (String) b.get("name");
            return nameA.compareTo(nameB);
        });

        StringBuilder out = new StringBuilder();
        out.append("=== Filtered Products (price > $50.00) ===\n");
        out.append("\n");

        double total = 0.0;
        for (Map<String, Object> p : filtered) {
            String name = (String) p.get("name");
            double price = ((Number) p.get("price")).doubleValue();
            total += price;
            out.append(String.format("%s: $%.2f%n", name, price));
        }

        out.append("\n");
        out.append(String.format("Count: %d%n", filtered.size()));
        out.append(String.format("Total: $%.2f%n", total));

        System.out.print(out.toString());
    }
}

