import * as fs from 'fs';

interface Edge {
  from: string;
  to: string;
  weight: number;
}

interface Graph {
  nodes: string[];
  edges: Edge[];
}

function main(): void {
  const filePath = '<tmp>';
  const data = fs.readFileSync(filePath, 'utf-8');
  const graph: Graph = JSON.parse(data);

  const nodes: string[] = graph.nodes;
  const edges: Edge[] = graph.edges;

  // Build adjacency list (undirected graph)
  const adj: Map<string, { to: string; weight: number }[]> = new Map();
  for (const node of nodes) {
    adj.set(node, []);
  }
  for (const edge of edges) {
    adj.get(edge.from)!.push({ to: edge.to, weight: edge.weight });
    adj.get(edge.to)!.push({ to: edge.from, weight: edge.weight });
  }

  // Dijkstra's algorithm
  const dist: Map<string, number> = new Map();
  for (const node of nodes) {
    dist.set(node, Infinity);
  }
  dist.set('A', 0);

  const unvisited: Set<string> = new Set(nodes);

  while (unvisited.size > 0) {
    // Find the unvisited node with the smallest distance
    let minNode: string | null = null;
    let minDist = Infinity;
    for (const node of unvisited) {
      const d = dist.get(node)!;
      if (d < minDist) {
        minDist = d;
        minNode = node;
      }
    }

    if (minNode === null || minDist === Infinity) break;

    unvisited.delete(minNode);

    // Relax all edges from minNode
    const neighbors = adj.get(minNode)!;
    for (const { to, weight } of neighbors) {
      if (unvisited.has(to)) {
        const newDist = dist.get(minNode)! + weight;
        if (newDist < dist.get(to)!) {
          dist.set(to, newDist);
        }
      }
    }
  }

  // Output
  const sorted = [...nodes].sort();
  const lines: string[] = [];
  lines.push('=== Shortest Paths from A ===');
  lines.push('');
  for (const node of sorted) {
    const d = dist.get(node)!;
    lines.push(`A -> ${node}: ${d}`);
  }
  process.stdout.write(lines.join('\n') + '\n');
}

main();

