use std::collections::{BTreeMap, BTreeSet};
use std::fs;

fn main() {
    let content = fs::read_to_string(
        "<tmp>",
    )
    .expect("Failed to read log file");

    let mut level_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_component_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_messages: BTreeSet<String> = BTreeSet::new();
    let mut hour_counts: BTreeMap<u32, usize> = BTreeMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        let start = match line.find('[') {
            Some(s) if s == 0 => s,
            _ => continue,
        };
        let end = match line.find(']') {
            Some(e) if e > start => e,
            _ => continue,
        };

        let timestamp = &line[start + 1..end];

        let rest = &line[end + 1..];
        let rest_trimmed = rest.trim_start();

        let level_end = rest_trimmed
            .find(' ')
            .unwrap_or(rest_trimmed.len());
        let level = &rest_trimmed[..level_end];

        let after_level = &rest_trimmed[level_end..];

        let paren_start = match after_level.find('(') {
            Some(p) => p,
            None => continue,
        };
        let paren_end = match after_level.find(')') {
            Some(p) if p > paren_start => p,
            _ => continue,
        };

        let component = &after_level[paren_start + 1..paren_end];

        let after_paren = &after_level[paren_end + 1..];

        let dash_pos = match after_paren.find(" - ") {
            Some(p) => p,
            None => continue,
        };

        let message = after_paren[dash_pos + 3..].trim();

        if timestamp.len() >= 13 {
            if let Ok(hour) = timestamp[11..13].parse::<u32>() {
                *hour_counts.entry(hour).or_insert(0) += 1;
            }
        }

        *level_counts.entry(level.to_string()).or_insert(0) += 1;

        if level == "ERROR" {
            *error_component_counts
                .entry(component.to_string())
                .or_insert(0) += 1;
            error_messages.insert(message.to_string());
        }
    }

    println!("=== Log Analysis ===");
    println!();
    println!("Entries by Level:");
    for (level, count) in &level_counts {
        println!("  {}: {}", level, count);
    }
    println!();

    let (best_comp, best_count) = error_component_counts
        .iter()
        .max_by_key(|(_, c)| *c)
        .map(|(k, c)| (k.as_str(), *c))
        .unwrap_or(("none", 0));
    println!("Component with Most Errors: {} ({} errors)", best_comp, best_count);
    println!();

    println!("Unique Error Messages:");
    for msg in &error_messages {
        println!("  - {}", msg);
    }
    println!();

    let (busiest_hour, busiest_count) = hour_counts
        .iter()
        .max_by_key(|(_, c)| *c)
        .map(|(h, c)| (*h, *c))
        .unwrap_or((0, 0));
    println!("Busiest Hour: {:02}:00 ({} entries)", busiest_hour, busiest_count);
}

