    static boolean deepContains(List<Object> list, Object target) {
        for (Object item : list) {
            if (deepEquals(item, target)) return true;
        }
        return false;
    }

    static boolean deepEquals(Object a, Object b) {
        if (a == null && b == null) return true;
        if (a == null || b == null) return false;
        if (a instanceof Map && b instanceof Map) {
            @SuppressWarnings("unchecked")
            Map<String, Object> ma = (Map<String, Object>) a;
            @SuppressWarnings("unchecked")
            Map<String, Object> mb = (Map<String, Object>) b;
            if (ma.size() != mb.size()) return false;
            for (Map.Entry<String, Object> entry : ma.entrySet()) {
                if (!mb.containsKey(entry.getKey())) return false;
                if (!deepEquals(entry.getValue(), mb.get(entry.getKey()))) return false;
            }
            return true;
        } else if (a instanceof List && b instanceof List) {
            @SuppressWarnings("unchecked")
            List<Object> la = (List<Object>) a;
            @SuppressWarnings("unchecked")
            List<Object> lb = (List<Object>) b;
            if (la.size() != lb.size()) return false;
            for (int i = 0; i < la.size(); i++) {
                if (!deepEquals(la.get(i), lb.get(i))) return false;
            }
            return true;
        } else if (a instanceof Number && b instanceof Number) {
            return ((Number) a).doubleValue() == ((Number) b).doubleValue();
        } else {
            return a.equals(b);
        }
    }

