#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *name;
    int count;
} NameCount;

static int cmp_namecount(const void *a, const void *b) {
    const NameCount *x = (const NameCount *)a;
    const NameCount *y = (const NameCount *)b;
    return strcmp(x->name, y->name);
}

static int cmp_strptr(const void *a, const void *b) {
    const char *const *x = (const char *const *)a;
    const char *const *y = (const char *const *)b;
    return strcmp(*x, *y);
}

int main(void) {
    const char *path = "<tmp>";

    FILE *f = fopen(path, "r");
    if (!f) {
        perror("fopen");
        return 1;
    }

    NameCount *levels = NULL;
    int nlevels = 0, cap_levels = 0;

    NameCount *comp_errors = NULL;
    int ncomp = 0, cap_comp = 0;

    char **error_msgs = NULL;
    int nmsgs = 0, cap_msgs = 0;

    int hours[24] = {0};

    char *line = NULL;
    size_t linecap = 0;

    while (getline(&line, &linecap, f) != -1) {
        /* Parse: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message */
        char *close_bracket = strchr(line, ']');
        if (!close_bracket) continue;

        /* hour at positions 12-13: [YYYY-MM-DD HH:MM:SS] */
        if (strlen(line) < 21) continue;
        if (line[12] < '0' || line[12] > '9' || line[13] < '0' || line[13] > '9') continue;
        int hour = (line[12] - '0') * 10 + (line[13] - '0');
        if (hour >= 0 && hour < 24) hours[hour]++;

        char *p = close_bracket + 1;
        if (*p == ' ') p++;

        /* Parse LEVEL */
        char *level_start = p;
        while (*p && *p != ' ' && *p != '(') p++;
        char *level_end = p;
        while (level_end > level_start && level_end[-1] == ' ') level_end--;

        char level[128] = {0};
        size_t ll = (size_t)(level_end - level_start);
        if (ll >= sizeof(level)) ll = sizeof(level) - 1;
        memcpy(level, level_start, ll);
        level[ll] = '\0';

        /* Count level */
        int found = 0;
        for (int i = 0; i < nlevels; i++) {
            if (strcmp(levels[i].name, level) == 0) {
                levels[i].count++;
                found = 1;
                break;
            }
        }
        if (!found) {
            if (nlevels >= cap_levels) {
                cap_levels = cap_levels ? cap_levels * 2 : 16;
                levels = realloc(levels, cap_levels * sizeof(NameCount));
                if (!levels) { fprintf(stderr, "OOM\n"); return 1; }
            }
            levels[nlevels].name = strdup(level);
            levels[nlevels].count = 1;
            nlevels++;
        }

        /* Skip to (component) */
        if (*p == ' ') p++;
        if (*p != '(') continue;
        p++;

        char *comp_start = p;
        while (*p && *p != ')') p++;
        char *comp_end = p;
        if (*p == ')') p++;

        char component[256] = {0};
        size_t cl = (size_t)(comp_end - comp_start);
        if (cl >= sizeof(component)) cl = sizeof(component) - 1;
        memcpy(component, comp_start, cl);
        component[cl] = '\0';

        int is_error = (strcmp(level, "ERROR") == 0);

        if (is_error) {
            int cfound = 0;
            for (int i = 0; i < ncomp; i++) {
                if (strcmp(comp_errors[i].name, component) == 0) {
                    comp_errors[i].count++;
                    cfound = 1;
                    break;
                }
            }
            if (!cfound) {
                if (ncomp >= cap_comp) {
                    cap_comp = cap_comp ? cap_comp * 2 : 16;
                    comp_errors = realloc(comp_errors, cap_comp * sizeof(NameCount));
                    if (!comp_errors) { fprintf(stderr, "OOM\n"); return 1; }
                }
                comp_errors[ncomp].name = strdup(component);
                comp_errors[ncomp].count = 1;
                ncomp++;
            }
        }

        /* Skip " - " to get message */
        if (*p == ' ') p++;
        if (*p == '-' && p[1] == ' ') p += 2;

        char *msg = p;
        size_t msglen = strlen(msg);
        while (msglen > 0 && (msg[msglen - 1] == '\n' || msg[msglen - 1] == '\r')) {
            msg[msglen - 1] = '\0';
            msglen--;
        }

        if (is_error && msglen > 0) {
            int mfound = 0;
            for (int i = 0; i < nmsgs; i++) {
                if (strcmp(error_msgs[i], msg) == 0) {
                    mfound = 1;
                    break;
                }
            }
            if (!mfound) {
                if (nmsgs >= cap_msgs) {
                    cap_msgs = cap_msgs ? cap_msgs * 2 : 64;
                    error_msgs = realloc(error_msgs, cap_msgs * sizeof(char *));
                    if (!error_msgs) { fprintf(stderr, "OOM\n"); return 1; }
                }
                error_msgs[nmsgs] = strdup(msg);
                nmsgs++;
            }
        }
    }

    free(line);
    fclose(f);

    /* Sort levels alphabetically */
    if (nlevels > 1)
        qsort(levels, nlevels, sizeof(NameCount), cmp_namecount);

    /* Find component with most errors (alphabetically first on tie) */
    int max_comp_idx = -1;
    int max_comp_count = 0;
    for (int i = 0; i < ncomp; i++) {
        if (comp_errors[i].count > max_comp_count ||
            (comp_errors[i].count == max_comp_count && max_comp_idx >= 0 &&
             strcmp(comp_errors[i].name, comp_errors[max_comp_idx].name) < 0)) {
            max_comp_count = comp_errors[i].count;
            max_comp_idx = i;
        }
    }

    /* Sort error messages alphabetically */
    if (nmsgs > 1)
        qsort(error_msgs, nmsgs, sizeof(char *), cmp_strptr);

    /* Find busiest hour */
    int busiest_hour = 0;
    int busiest_count = 0;
    for (int i = 0; i < 24; i++) {
        if (hours[i] > busiest_count) {
            busiest_count = hours[i];
            busiest_hour = i;
        }
    }

    /* Output */
    printf("=== Log Analysis ===\n");
    printf("\n");
    printf("Entries by Level:\n");
    for (int i = 0; i < nlevels; i++) {
        printf("  %s: %d\n", levels[i].name, levels[i].count);
    }
    printf("\n");
    if (max_comp_idx >= 0) {
        printf("Component with Most Errors: %s (%d errors)\n", comp_errors[max_comp_idx].name, max_comp_count);
    } else {
        printf("Component with Most Errors: N/A (0 errors)\n");
    }
    printf("\n");
    printf("Unique Error Messages:\n");
    for (int i = 0; i < nmsgs; i++) {
        printf("  - %s\n", error_msgs[i]);
    }
    printf("\n");
    printf("Busiest Hour: %02d:00 (%d entries)\n", busiest_hour, busiest_count);

    /* Cleanup */
    for (int i = 0; i < nlevels; i++) free(levels[i].name);
    free(levels);
    for (int i = 0; i < ncomp; i++) free(comp_errors[i].name);
    free(comp_errors);
    for (int i = 0; i < nmsgs; i++) free(error_msgs[i]);
    free(error_msgs);

    return 0;
}
