static void skip_ws(void) {
    while (pos < src_len) {
        char c = src[pos];
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r') pos++;
        else break;
    }
}

static JsonValue *parse_value(void);

static char *parse_string_raw(void) {
    /* assumes src[pos] == '"' */
    pos++; /* skip opening quote */
    long cap = 256;
    long len = 0;
    char *buf = (char *)malloc(cap);
    if (!buf) { fprintf(stderr, "OOM\n"); exit(1); }
    while (pos < src_len && src[pos] != '"') {
        if (len + 8 >= cap) {
            cap *= 2;
            buf = (char *)realloc(buf, cap);
            if (!buf) { fprintf(stderr, "OOM\n"); exit(1); }
        }
        char c = src[pos];
        if (c == '\\') {
            pos++;
            char esc = src[pos];
            switch (esc) {
                case '"': buf[len++] = '"'; pos++; break;
                case '\\': buf[len++] = '\\'; pos++; break;
                case '/': buf[len++] = '/'; pos++; break;
                case 'b': buf[len++] = '\b'; pos++; break;
                case 'f': buf[len++] = '\f'; pos++; break;
                case 'n': buf[len++] = '\n'; pos++; break;
                case 'r': buf[len++] = '\r'; pos++; break;
                case 't': buf[len++] = '\t'; pos++; break;
                case 'u': {
                    /* parse 4 hex digits, encode as UTF-8 */
                    unsigned int cp = 0;
                    for (int i = 0; i < 4; i++) {
                        char h = src[pos++];
                        cp <<= 4;
                        if (h >= '0' && h <= '9') cp |= (h - '0');
                        else if (h >= 'a' && h <= 'f') cp |= (h - 'a' + 10);
                        else if (h >= 'A' && h <= 'F') cp |= (h - 'A' + 10);
