                    /* check for surrogate pair */
                    if (cp >= 0xD800 && cp <= 0xDBFF && pos + 1 < src_len && src[pos] == '\\' && src[pos+1] == 'u') {
                        pos += 2;
                        unsigned int lo = 0;
                        for (int i = 0; i < 4; i++) {
                            char h = src[pos++];
                            lo <<= 4;
                            if (h >= '0' && h <= '9') lo |= (h - '0');
                            else if (h >= 'a' && h <= 'f') lo |= (h - 'a' + 10);
                            else if (h >= 'A' && h <= 'F') lo |= (h - 'A' + 10);
                        }
                        cp = 0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00);
                    }
                    /* encode UTF-8 */
                    if (cp < 0x80) {
                        buf[len++] = (char)cp;
                    } else if (cp < 0x800) {
                        buf[len++] = (char)(0xC0 | (cp >> 6));
                        buf[len++] = (char)(0x80 | (cp & 0x3F));
                    } else if (cp < 0x10000) {
                        buf[len++] = (char)(0xE0 | (cp >> 12));
                        buf[len++] = (char)(0x80 | ((cp >> 6) & 0x3F));
                        buf[len++] = (char)(0x80 | (cp & 0x3F));
                    } else {
                        buf[len++] = (char)(0xF0 | (cp >> 18));
                        buf[len++] = (char)(0x80 | ((cp >> 12) & 0x3F));
                        buf[len++] = (char)(0x80 | ((cp >> 6) & 0x3F));
                        buf[len++] = (char)(0x80 | (cp & 0x3F));
                    }
                    break;
                }
                default:
                    buf[len++] = esc;
                    pos++;
                    break;
            }
        } else {
            buf[len++] = c;
            pos++;
        }
    }
    if (pos < src_len) pos++; /* skip closing quote */
    buf[len] = '\0';
    return buf;
}

static JsonValue *parse_string(void) {
    JsonValue *v = json_new();
    v->type = JSON_STRING;
    v->string = parse_string_raw();
    return v;
}

static JsonValue *parse_number(void) {
    long start = pos;
    while (pos < src_len) {
        char c = src[pos];
        if (isdigit((unsigned char)c) || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E')
            pos++;
        else break;
    }
    char *numstr = (char *)malloc(pos - start + 1);
    if (!numstr) { fprintf(stderr, "OOM\n"); exit(1); }
    memcpy(numstr, src + start, pos - start);
    numstr[pos - start] = '\0';
    JsonValue *v = json_new();
    v->type = JSON_NUMBER;
    v->number = strtod(numstr, NULL);
    free(numstr);
    return v;
}

static JsonValue *parse_array(void) {
    pos++; /* skip [ */
    JsonValue *v = json_new();
    v->type = JSON_ARRAY;
    skip_ws();
    if (pos < src_len && src[pos] == ']') {
        pos++;
        return v;
    }
    while (1) {
        skip_ws();
        JsonValue *item = parse_value();
        array_push(v, item);
        skip_ws();
        if (pos < src_len && src[pos] == ',') {
