static JsonValue *parse_object(void) {
    pos++; /* skip { */
    JsonValue *v = json_new();
    v->type = JSON_OBJECT;
    skip_ws();
    if (pos < src_len && src[pos] == '}') {
        pos++;
        return v;
    }
    while (1) {
        skip_ws();
        char *key = parse_string_raw();
        skip_ws();
        if (pos >= src_len || src[pos] != ':') { free(key); fprintf(stderr, "Parse error\n"); exit(1); }
        pos++; /* skip : */
        skip_ws();
        JsonValue *val = parse_value();
        object_add(v, key, val);
