}

static JsonValue *parse_value(void) {
    skip_ws();
    if (pos >= src_len) { fprintf(stderr, "Unexpected end\n"); exit(1); }
    char c = src[pos];
    if (c == '{') return parse_object();
    if (c == '[') return parse_array();
    if (c == '"') return parse_string();
    if (c == 't') { pos += 4; JsonValue *v = json_new(); v->type = JSON_BOOL; v->boolean = 1; return v; }
