/* Deep clone */
static JsonValue *json_clone(const JsonValue *v) {
    JsonValue *c = json_new();
    c->type = v->type;
    switch (v->type) {
        case JSON_NULL: break;
        case JSON_BOOL: c->boolean = v->boolean; break;
        case JSON_NUMBER: c->number = v->number; break;
        case JSON_STRING: c->string = strdup(v->string); break;
        case JSON_ARRAY:
            c->item_cap = v->item_count;
            c->items = (JsonValue **)calloc(v->item_count, sizeof(JsonValue *));
            for (int i = 0; i < v->item_count; i++) {
                c->items[i] = json_clone(v->items[i]);
                c->item_count++;
            }
            break;
        case JSON_OBJECT:
            c->pair_cap = v->pair_count;
            c->keys = (char **)calloc(v->pair_count, sizeof(char *));
            c->values = (JsonValue **)calloc(v->pair_count, sizeof(JsonValue *));
            for (int i = 0; i < v->pair_count; i++) {
                c->keys[i] = strdup(v->keys[i]);
                c->values[i] = json_clone(v->values[i]);
                c->pair_count++;
            }
