/* Merge: B into A (result is a new value) */
static JsonValue *json_merge(const JsonValue *a, const JsonValue *b) {
    /* If both objects: merge recursively */
    if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
        JsonValue *result = json_new();
        result->type = JSON_OBJECT;
        /* Start with all keys from A */
        for (int i = 0; i < a->pair_count; i++) {
            JsonValue *val = json_clone(a->values[i]);
            /* Check if key exists in B */
            int found = 0;
            for (int j = 0; j < b->pair_count; j++) {
                if (strcmp(a->keys[i], b->keys[j]) == 0) {
                    val = json_merge(a->values[i], b->values[j]);
                    found = 1;
                    break;
                }
            }
            if (!found) {
                /* key only in A, include as-is */
            }
            object_add(result, a->keys[i], val);
        }
        /* Add keys only in B */
        for (int j = 0; j < b->pair_count; j++) {
            int found = 0;
            for (int i = 0; i < a->pair_count; i++) {
                if (strcmp(b->keys[j], a->keys[i]) == 0) { found = 1; break; }
            }
            if (!found) {
                object_add(result, b->keys[j], json_clone(b->values[j]));
            }
        }
        return result;
    }
    /* If both arrays: concatenate, remove duplicates */
    if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        JsonValue *result = json_new();
        result->type = JSON_ARRAY;
        /* Add all items from A */
        for (int i = 0; i < a->item_count; i++) {
            array_push(result, json_clone(a->items[i]));
        }
        /* Add items from B that are not already in result */
        for (int j = 0; j < b->item_count; j++) {
            int dup = 0;
            for (int i = 0; i < result->item_count; i++) {
                if (json_equal(result->items[i], b->items[j])) { dup = 1; break; }
            }
            if (!dup) {
                array_push(result, json_clone(b->items[j]));
            }
        }
