import java.util.*;

public class Main {
    static class FileInfo {
        String relPath;
        long lines;
        long chars;
        FileInfo(String relPath, long lines, long chars) {
            this.relPath = relPath;
            this.lines = lines;
            this.chars = chars;
        }
    }

    public static void main(String[] args) throws Exception {
        Path root = Paths.get("<tmp>");
        Map<String, List<FileInfo>> byExt = new TreeMap<>();
        Set<Path> visitedDirs = new HashSet<>();

        walk(root, root, byExt, visitedDirs);

        long totalFiles = 0;
        long totalLines = 0;
        long totalChars = 0;
        for (List<FileInfo> files : byExt.values()) {
            for (FileInfo fi : files) {
                totalFiles++;
                totalLines += fi.lines;
                totalChars += fi.chars;
            }
        }

        StringBuilder sb = new StringBuilder();
        sb.append("=== File Tree Analysis ===\n");
        sb.append("\n");

        for (Map.Entry<String, List<FileInfo>> entry : byExt.entrySet()) {
            String ext = entry.getKey();
            List<FileInfo> files = entry.getValue();
            Collections.sort(files, (a, b) -> a.relPath.compareTo(b.relPath));

            long extLines = 0;
            long extChars = 0;
            for (FileInfo fi : files) {
                extLines += fi.lines;
                extChars += fi.chars;
            }

            sb.append("Extension: ").append(ext).append("\n");
            sb.append("  Files: ").append(files.size()).append("\n");
            sb.append("  Total Lines: ").append(extLines).append("\n");
            sb.append("  Total Characters: ").append(extChars).append("\n");
            for (FileInfo fi : files) {
                sb.append("    ").append(fi.relPath).append(": ").append(fi.lines).append(" lines, ").append(fi.chars).append(" chars\n");
            }
        }

        sb.append("\n");
        sb.append("Total: ").append(totalFiles).append(" files, ").append(totalLines).append(" lines, ").append(totalChars).append(" characters\n");

        System.out.print(sb.toString());
    }

    static void walk(Path dir, Path root, Map<String, List<FileInfo>> byExt, Set<Path> visitedDirs) throws IOException {
        if (Files.isSymbolicLink(dir)) return;
        if (!Files.isDirectory(dir)) return;

        Path real;
        try {
            real = dir.toRealPath();
        } catch (IOException e) {
            return;
        }
        if (!visitedDirs.add(real)) return;

        try (DirectoryStream<Path> stream = Files.newDirectoryStream(dir)) {
            List<Path> entries = new ArrayList<>();
            stream.forEach(entries::add);
            entries.sort(Comparator.comparing(p -> p.getFileName().toString()));
            for (Path entry : entries) {
                if (Files.isSymbolicLink(entry)) continue;
                if (Files.isDirectory(entry)) {
                    walk(entry, root, byExt, visitedDirs);
                } else if (Files.isRegularFile(entry)) {
                    long lines = countLines(entry);
                    long chars = Files.size(entry);
                    String relPath = root.relativize(entry).toString().replace('\\', '/');
                    String ext = getExtension(entry.getFileName().toString());
                    byExt.computeIfAbsent(ext, k -> new ArrayList<>()).add(new FileInfo(relPath, lines, chars));
                }
            }
        }
    }

    static long countLines(Path file) throws IOException {
        long lines = 0;
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(new FileInputStream(file.toFile()), "ISO-8859-1"))) {
            while (reader.readLine() != null) {
                lines++;
            }
        }
        return lines;
    }

    static String getExtension(String filename) {
        int lastDot = filename.lastIndexOf('.');
        if (lastDot <= 0) return "";
        return filename.substring(lastDot);
    }
}

