public class Main {
    public static void main(String[] args) throws Exception {
        String path = "<tmp>";

        StringBuilder sb = new StringBuilder();
        try (BufferedReader br = new BufferedReader(new FileReader(path))) {
            String line;
            while ((line = br.readLine()) != null) {
                sb.append(line);
            }
        }
        String json = sb.toString();

        // Parse nodes
        List<String> nodes = new ArrayList<>();
        int nodesKey = json.indexOf("\"nodes\"");
        int arrStart = json.indexOf('[', nodesKey);
        int arrEnd = findMatchingChar(json, arrStart, '[', ']');
        String nodesContent = json.substring(arrStart + 1, arrEnd);
        Matcher m = Pattern.compile("\"([^\"]*)\"").matcher(nodesContent);
        while (m.find()) {
            nodes.add(m.group(1));
        }

        // Parse edges
        List<String[]> edges = new ArrayList<>();
        int edgesKey = json.indexOf("\"edges\"");
        int edgesArrStart = json.indexOf('[', edgesKey);
        int edgesArrEnd = findMatchingChar(json, edgesArrStart, '[', ']');
        String edgesContent = json.substring(edgesArrStart, edgesArrEnd + 1);

        int pos = 0;
        while (pos < edgesContent.length()) {
            int objStart = edgesContent.indexOf('{', pos);
            if (objStart == -1) break;
            int objEnd = findMatchingChar(edgesContent, objStart, '{', '}');
            String objStr = edgesContent.substring(objStart, objEnd + 1);
            String from = extractString(objStr, "from");
            String to = extractString(objStr, "to");
            String weight = extractNumber(objStr, "weight");
            edges.add(new String[]{from, to, weight});
            pos = objEnd + 1;
        }

        // Build adjacency list (undirected)
        Map<String, List<String[]>> adj = new HashMap<>();
        for (String n : nodes) adj.put(n, new ArrayList<>());
        for (String[] e : edges) {
            adj.get(e[0]).add(new String[]{e[1], e[2]});
            adj.get(e[1]).add(new String[]{e[0], e[2]});
        }

        // Dijkstra's algorithm
        int n = nodes.size();
        Map<String, Integer> nodeIndex = new HashMap<>();
        for (int i = 0; i < n; i++) nodeIndex.put(nodes.get(i), i);

        int[] dist = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        int srcIdx = nodeIndex.get("A");
        dist[srcIdx] = 0;
        boolean[] visited = new boolean[n];

        for (int i = 0; i < n; i++) {
            int u = -1;
            for (int j = 0; j < n; j++) {
                if (!visited[j] && (u == -1 || dist[j] < dist[u])) {
                    u = j;
                }
            }
            if (u == -1 || dist[u] == Integer.MAX_VALUE) break;
            visited[u] = true;

            for (String[] neighbor : adj.get(nodes.get(u))) {
                int vIdx = nodeIndex.get(neighbor[0]);
                int w = Integer.parseInt(neighbor[1]);
                if (!visited[vIdx] && dist[u] + w < dist[vIdx]) {
                    dist[vIdx] = dist[u] + w;
                }
            }
        }

        // Output
        System.out.println("=== Shortest Paths from A ===");
        System.out.println();

        List<String> sorted = new ArrayList<>(nodes);
        Collections.sort(sorted);

        for (String node : sorted) {
            int d = dist[nodeIndex.get(node)];
            if (d == Integer.MAX_VALUE) {
                System.out.println("A -> " + node + ": unreachable");
            } else {
                System.out.println("A -> " + node + ": " + d);
            }
        }
    }

    static int findMatchingChar(String s, int start, char open, char close) {
        int depth = 0;
        for (int i = start; i < s.length(); i++) {
            if (s.charAt(i) == open) depth++;
            else if (s.charAt(i) == close) {
                depth--;
                if (depth == 0) return i;
            }
        }
        return s.length() - 1;
    }

