#include <stdlib.h>
#include <string.h>

static char *run_command(const char *cmd) {
    FILE *fp = popen(cmd, "r");
    if (!fp) return NULL;

    size_t cap = 4096;
    size_t len = 0;
    char *buf = (char *)malloc(cap);
    if (!buf) {
        pclose(fp);
        return NULL;
    }

    size_t n;
    while ((n = fread(buf + len, 1, cap - len - 1, fp)) > 0) {
        len += n;
        if (len + 1 >= cap) {
            cap *= 2;
            char *tmp = (char *)realloc(buf, cap);
            if (!tmp) {
                free(buf);
                pclose(fp);
                return NULL;
            }
            buf = tmp;
        }
    }
    pclose(fp);
    buf[len] = '\0';

    while (len > 0 &&
           (buf[len - 1] == '\n' || buf[len - 1] == '\r' ||
            buf[len - 1] == ' '  || buf[len - 1] == '\t')) {
        buf[--len] = '\0';
    }

    return buf;
}

int main(void) {
    char *os       = run_command("uname -s");
    char *arch     = run_command("uname -m");
    char *username = run_command("whoami");
    char *hostname = run_command("hostname");

    if (!os || !arch || !username || !hostname) {
        fprintf(stderr, "Error: failed to run a system command\n");
        free(os);
        free(arch);
        free(username);
        free(hostname);
        return 1;
    }

    printf("{\n");
    printf("  \"hostname\": \"%s\",\n", hostname);
    printf("  \"os\": \"%s\",\n", os);
    printf("  \"architecture\": \"%s\",\n", arch);
    printf("  \"username\": \"%s\"\n", username);
    printf("}\n");

    free(os);
    free(arch);
    free(username);
    free(hostname);
    return 0;
}

