use std::collections::BTreeMap;
use std::fs;

#[derive(Debug, Clone, PartialEq)]
enum Value {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Value>),
    Object(BTreeMap<String, Value>),
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        let mut chars: Vec<char> = s.chars().collect();
        // Strip BOM if present
        if chars.first() == Some(&'\u{FEFF}') {
            chars.remove(0);
        }
        Parser { chars, pos: 0 }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_whitespace() {
            self.pos += 1;
        }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn expect(&mut self, c: char) -> Result<(), String> {
        self.skip_whitespace();
        match self.next() {
            Some(ch) if ch == c => Ok(()),
            _ => Err(format!("Expected '{}', got {:?} at position {}", c, self.peek(), self.pos)),
        }
    }

    fn parse_value(&mut self) -> Result<Value, String> {
        self.skip_whitespace();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => Ok(Value::String(self.parse_string()?)),
            Some('t') => self.parse_literal("true", Value::Bool(true)),
            Some('f') => self.parse_literal("false", Value::Bool(false)),
            Some('n') => self.parse_literal("null", Value::Null),
            Some(c) if c == '-' || c.is_ascii_digit() => self.parse_number(),
            _ => Err(format!("Unexpected character {:?} at position {}", self.peek(), self.pos)),
        }
    }

    fn parse_literal(&mut self, literal: &str, value: Value) -> Result<Value, String> {
        for expected in literal.chars() {
            match self.next() {
                Some(c) if c == expected => {}
                _ => return Err(format!("Expected literal '{}'", literal)),
            }
        }
        Ok(value)
    }

    fn parse_hex4(&mut self) -> Result<u32, String> {
        let mut code: u32 = 0;
        for _ in 0..4 {
            let c = self.next().ok_or("Unexpected end of input in \\u escape")?;
            let d = match c {
                '0'..='9' => (c as u32) - ('0' as u32),
                'a'..='f' => (c as u32) - ('a' as u32) + 10,
                'A'..='F' => (c as u32) - ('A' as u32) + 10,
                _ => return Err(format!("Invalid hex digit '{}'", c)),
            };
            code = code * 16 + d;
        }
        Ok(code)
    }

    fn parse_string(&mut self) -> Result<String, String> {
        self.expect('"')?;
        let mut s = String::new();
        loop {
            match self.next() {
                None => return Err("Unexpected end of input in string".into()),
                Some('"') => break,
                Some('\\') => {
                    match self.next() {
                        Some('"') => s.push('"'),
                        Some('\\') => s.push('\\'),
                        Some('/') => s.push('/'),
                        Some('b') => s.push('\u{0008}'),
                        Some('f') => s.push('\u{000C}'),
                        Some('n') => s.push('\n'),
                        Some('r') => s.push('\r'),
                        Some('t') => s.push('\t'),
                        Some('u') => {
                            let high = self.parse_hex4()?;
                            if (0xD800..=0xDBFF).contains(&high) {
                                if self.next() == Some('\\') && self.next() == Some('u') {
                                    let low = self.parse_hex4()?;
                                    if (0xDC00..=0xDFFF).contains(&low) {
                                        let cp = 0x10000 + ((high - 0xD800) << 10) + (low - 0xDC00);
                                        s.push(char::from_u32(cp).ok_or("Invalid code point")?);
                                    } else {
                                        return Err("Invalid low surrogate".into());
                                    }
                                } else {
                                    return Err("Expected low surrogate".into());
                                }
                            } else {
                                s.push(char::from_u32(high).ok_or("Invalid code point")?);
                            }
                        }
                        _ => return Err("Invalid escape sequence".into()),
                    }
                }
                Some(c) => s.push(c),
            }
        }
        Ok(s)
    }

    fn parse_number(&mut self) -> Result<Value, String> {
        let start = self.pos;
