use std::collections::BTreeMap;
use std::fs;
use std::path::Path;

fn main() {
    let base = Path::new("<tmp>");

    let mut files: Vec<(String, u64, u64)> = Vec::new();

    if base.is_dir() {
        walk(base, base, &mut files);
    }

    let mut groups: BTreeMap<String, Vec<(String, u64, u64)>> = BTreeMap::new();

    for (rel_path, lines, chars) in &files {
        let p = Path::new(rel_path);
        let ext = p.extension()
            .map(|e| format!(".{}", e))
            .unwrap_or_else(|| "(none)".to_string());
        groups.entry(ext).or_default().push((rel_path.clone(), *lines, *chars));
    }

    for v in groups.values_mut() {
        v.sort_by(|a, b| a.0.cmp(&b.0));
    }

    println!("=== File Tree Analysis ===");
    println!();

    let mut total_files: u64 = 0;
    let mut total_lines: u64 = 0;
    let mut total_chars: u64 = 0;

    for (ext, file_list) in &groups {
        let n_files = file_list.len() as u64;
        let n_lines: u64 = file_list.iter().map(|f| f.1).sum();
        let n_chars: u64 = file_list.iter().map(|f| f.2).sum();

        println!("Extension: {}", ext);
        println!("  Files: {}", n_files);
        println!("  Total Lines: {}", n_lines);
        println!("  Total Characters: {}", n_chars);

        for (rel_path, lines, chars) in file_list {
            println!("    {}: {} lines, {} chars", rel_path, lines, chars);
        }

        total_files += n_files;
        total_lines += n_lines;
        total_chars += n_chars;
    }

    println!();
    println!("Total: {} files, {} lines, {} characters", total_files, total_lines, total_chars);
}

fn walk(base: &Path, dir: &Path, files: &mut Vec<(String, u64, u64)>) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };

    for entry in entries {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };

