import Foundation

let baseDir = "<tmp>"
let fm = FileManager.default

struct FileInfo {
    let relativePath: String
    let ext: String
    let lines: Int
    let chars: Int
}

var visitedDirs = Set<String>()
var allFiles: [FileInfo] = []

func walk(_ dir: String) {
    let dirURL = URL(fileURLWithPath: dir)
    guard let contents = try? fm.contentsOfDirectory(
        at: dirURL,
        includingPropertiesForKeys: [.isRegularFileKey, .isDirectoryKey, .isSymbolicLinkKey],
        options: []
    ) else { return }

    for item in contents {
        let itemPath = item.path
        let values = try? item.resourceValues(forKeys: [.isSymbolicLinkKey, .isDirectoryKey])
        let isSymlink = values?.isSymbolicLink ?? false
        let isDir = values?.isDirectory ?? false

        if isSymlink {
            continue
        }

        if isDir {
            if !visitedDirs.contains(itemPath) {
                visitedDirs.insert(itemPath)
                walk(itemPath)
            }
        } else {
            let prefix = baseDir + "/"
            let rel: String
            if itemPath.hasPrefix(prefix) {
                rel = String(itemPath.dropFirst(prefix.count))
            } else {
                rel = itemPath
            }

            let ext = (itemPath as NSString).pathExtension
            let extStr = ext.isEmpty ? "" : "." + ext

            let attrs = try? fm.attributesOfItem(atPath: itemPath)
            let size = (attrs?[.size] as? Int) ?? 0

            var lineCount = 0
            if size > 0 {
                if let data = try? Data(contentsOf: URL(fileURLWithPath: itemPath)) {
                    let bytes = [UInt8](data)
                    var lines = 0
                    for b in bytes {
                        if b == 0x0A {
                            lines += 1
                        }
                    }
                    if let last = bytes.last, last != 0x0A {
                        lines += 1
                    }
                    lineCount = lines
                }
            }

            allFiles.append(FileInfo(relativePath: rel, ext: extStr, lines: lineCount, chars: size))
        }
    }
}

