enum Json {
    Null,
    Bool(bool),
    Number(f64),
    Str(String),
    Array(Vec<Json>),
    Object(Vec<(String, Json)>),
}

struct Parser<'a> {
    data: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Parser { data: s.as_bytes(), pos: 0 }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.data.len() {
            let b = self.data[self.pos];
            if b == b' ' || b == b'\t' || b == b'\n' || b == b'\r' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn peek(&self) -> Option<u8> {
        self.data.get(self.pos).copied()
    }

    fn expect(&mut self, c: u8) -> Result<(), &'static str> {
        self.skip_whitespace();
        if self.peek() == Some(c) {
            self.pos += 1;
            Ok(())
        } else {
            Err("unexpected character")
        }
    }

    fn parse_value(&mut self) -> Result<Json, &'static str> {
        self.skip_whitespace();
        match self.peek() {
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b'"') => self.parse_string().map(Json::Str),
            Some(b't') => {
                self.pos += 4;
                Ok(Json::Bool(true))
            }
            Some(b'f') => {
                self.pos += 5;
                Ok(Json::Bool(false))
            }
            Some(b'n') => {
                self.pos += 4;
                Ok(Json::Null)
            }
            _ => self.parse_number(),
        }
    }

    fn parse_string(&mut self) -> Result<String, &'static str> {
        self.expect(b'"')?;
        let mut s = String::new();
        loop {
            if self.pos >= self.data.len() {
                return Err("unterminated string");
            }
            let c = self.data[self.pos] as char;
            self.pos += 1;
            match c {
                '"' => break,
                '\\' => {
                    if self.pos >= self.data.len() {
                        return Err("unterminated escape");
                    }
                    let esc = self.data[self.pos] as char;
                    self.pos += 1;
                    match esc {
                        '"' => s.push('"'),
                        '\\' => s.push('\\'),
                        '/' => s.push('/'),
                        'n' => s.push('\n'),
                        't' => s.push('\t'),
                        'r' => s.push('\r'),
                        'b' => s.push('\u{0008}'),
                        'f' => s.push('\u{000C}'),
                        'u' => {
                            let mut code: u32 = 0;
                            for _ in 0..4 {
                                if self.pos >= self.data.len() {
                                    return Err("invalid unicode escape");
                                }
                                let h = self.data[self.pos] as char;
                                self.pos += 1;
                                code = code * 16 + h.to_digit(16).unwrap_or(0);
                            }
                            s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                        }
                        _ => return Err("invalid escape"),
                    }
                }
                _ => s.push(c),
            }
        }
        Ok(s)
    }

    fn parse_number(&mut self) -> Result<Json, &'static str> {
