fn parse_json(s: &str) -> Result<Json, &'static str> {
    let mut p = Parser::new(s);
    p.parse_value()
}

fn dechunk(data: &str) -> String {
    let mut result = String::new();
    let mut pos = 0;
    while pos < data.len() {
        let line_end = data[pos..].find("\r\n").unwrap_or(usize::MAX);
        if line_end == usize::MAX {
            break;
        }
        let size_str = &data[pos..pos + line_end];
        let size = usize::from_str_radix(size_str.trim(), 16).unwrap_or(0);
        pos += line_end + 2;
        if size == 0 {
            break;
        }
        if pos + size <= data.len() {
            result.push_str(&data[pos..pos + size]);
            pos += size;
            pos += 2;
        } else {
            break;
        }
    }
    result
}

fn http_get(url: &str) -> Result<String, Box<dyn std::error::Error>> {
    let without_scheme = url.trim_start_matches("http://");
    let mut parts = without_scheme.splitn(2, '/');
    let host_port = parts.next().unwrap_or("");
    let path = parts.next().unwrap_or("");
    let full_path = if path.is_empty() { "/" } else { path };

    let addr = if host_port.contains(':') {
        host_port.to_string()
    } else {
        format!("{}:80", host_port)
    };

    let mut stream = TcpStream::connect(&addr)?;

    let request = format!(
        "GET {} HTTP/1.1\r\nHost: {}\r\nConnection: close\r\n\r\n",
        full_path, host_port
    );

    stream.write_all(request.as_bytes())?;

    let mut response = Vec::new();
    let mut buf = [0u8; 4096];
    loop {
        let n = stream.read(&mut buf)?;
        if n == 0 {
            break;
        }
        response.extend_from_slice(&buf[..n]);
    }

    let response_str = String::from_utf8(response)?;

    let body_start = response_str
        .find("\r\n\r\n")
        .map(|i| i + 4)
        .unwrap_or(0);

    let headers_end = body_start.saturating_sub(4).min(response_str.len());
    let headers = &response_str[..headers_end];
    let mut body = response_str[body_start..].to_string();

    let headers_lower = headers.to_lowercase();
    if headers_lower.contains("transfer-encoding: chunked") {
        body = dechunk(&body);
    }

    Ok(body)
}

