        if (found == -1) {
            if (dept_n >= dept_cap) {
                dept_cap *= 2;
                depts = (Dept *)realloc(depts, (size_t)dept_cap * sizeof(Dept));
                if (!depts) { free(line); fclose(f); return 1; }
            }
            found = dept_n++;
            strncpy(depts[found].name, dept_name, 255);
            depts[found].name[255] = '\0';
            depts[found].count = 0;
            depts[found].sum = 0.0;
        }
        depts[found].count++;
        depts[found].sum += salary;

        long sal_int = (long)(salary + 0.5);
        total_budget += sal_int;

        if (sal_int > highest_salary) {
            highest_salary = sal_int;
            strncpy(highest_name, name, 255);
            highest_name[255] = '\0';
        }
    }

    free(line);
    fclose(f);

    qsort(depts, (size_t)dept_n, sizeof(Dept), dept_compare);

    printf("=== Salary Report ===\n");
    printf("\n");
    printf("Average Salary by Department:\n");
    for (int i = 0; i < dept_n; i++) {
        char buf[128];
        double avg = depts[i].sum / (double)depts[i].count;
        format_avg_with_commas(avg, buf, sizeof(buf));
        printf("  %s: %s\n", depts[i].name, buf);
    }
    printf("\n");

    char buf[128];
    format_int_with_commas(highest_salary, buf, sizeof(buf));
    printf("Highest Paid: %s (%s)\n", highest_name, buf);
    printf("\n");

    printf("Departments with >2 employees:\n");
    for (int i = 0; i < dept_n; i++) {
        if (depts[i].count > 2) {
            printf("  %s (%ld employees)\n", depts[i].name, depts[i].count);
        }
    }
    printf("\n");

    format_int_with_commas(total_budget, buf, sizeof(buf));
    printf("Total Budget: %s\n", buf);

    free(depts);
    return 0;
}
